def count_01_subsets(weights, target):
    if target < 0:
        return None
    for weight in weights:
        if weight < 0:
            return None
    ways = [0] * (target + 1)
    ways[0] = 1
    for weight in weights:
        total = target
        while total >= weight:
            ways[total] = ways[total] + ways[total - weight]
            total = total - 1
    return ways[target]

